'use client'

import { Product } from '@/../types/products'
import Image from 'next/image'

interface ProductModalProps {
  product: Product | null
  onClose: () => void
}

export default function ProductModal({ product, onClose }: ProductModalProps) {
  if (!product) return null

  return (
    <div className="fixed inset-0 flex items-center justify-center bg-black/50 z-50">
      <div className="bg-white w-[650px] rounded-xl shadow-2xl p-6 relative">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-500 hover:text-black text-xl"
        >
          ✕
        </button>

        {/* Product Details */}
        <div className="flex gap-6">
          {/* Product Image */}
          <div className="w-[220px] h-[220px] relative flex-shrink-0">
            <Image
              src={product.images[0]}
              alt={product.title}
              fill
              className="rounded-lg object-cover"
            />
          </div>

          {/* Product Info */}
          <div className="flex-1">
            <h2 className="text-2xl font-semibold mb-3 text-gray-800">
              {product.title}
            </h2>

            {/* Description (render HTML safely) */}
            <div
              className="text-gray-600 text-sm mb-5 leading-relaxed"
              dangerouslySetInnerHTML={{ __html: product.description }}
            />

            {/* Product Attributes */}
            <div className="grid grid-cols-2 gap-y-3 gap-x-6 text-sm text-gray-700">
              <p>
                <strong>MSRP:</strong> ${product.msrp}
              </p>
              <p>
                <strong>MOQ:</strong> {product.moq}
              </p>
              <p>
                <strong>Unit Price:</strong> ${product.unitPrice}
              </p>
              <p>
                <strong>Discount Price:</strong> ${product.discountPrice}
              </p>
              <p>
                <strong>Quantity:</strong> {product.quantity}
              </p>
              <p>
                <strong>Brand:</strong> {product.brand}
              </p>
              <p>
                <strong>Category:</strong> {product.category?.name}
              </p>
              <p>
                <strong>Status:</strong> {product.status}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
